import * as React from "react"
import {
  ArrowDown02Icon,
  ArrowUp02Icon,
  Copy01Icon,
  Delete02Icon,
} from "@hugeicons/core-free-icons"
import { DragHandle } from "@tiptap/extension-drag-handle-react"
import type { Node as PMNode } from "@tiptap/pm/model"
import { TextSelection } from "@tiptap/pm/state"
import type { Editor } from "@tiptap/react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Icon } from "../icon"
import { BLOCK_COMMANDS, hasExtension } from "./commands"
import type { RichTextActions } from "./types"

// Blocks "Turn into" can convert: text blocks, lists and quotes.
const CONVERTIBLE = new Set([
  "paragraph",
  "heading",
  "codeBlock",
  "blockquote",
  "bulletList",
  "orderedList",
  "taskList",
])

const TURN_INTO = [
  "paragraph",
  "heading-1",
  "heading-2",
  "heading-3",
  "bullet-list",
  "ordered-list",
  "task-list",
  "quote",
  "code-block",
]

type Target = { node: PMNode | null; pos: number }

/**
 * The handle beside the hovered block: `+` adds a block below through the
 * `/` menu; the grip drags the block, and clicking it opens a menu to turn
 * it into another kind, move, duplicate or delete it.
 */
export function BlockHandle({
  editor,
  actions,
}: {
  editor: Editor
  actions: RichTextActions
}) {
  const target = React.useRef<Target>({ node: null, pos: -1 })
  const [menuOpen, setMenuOpen] = React.useState(false)
  const [menuTarget, setMenuTarget] = React.useState<Target | null>(null)

  const openMenu = (open: boolean) => {
    setMenuOpen(open)
    setMenuTarget(open ? target.current : null)
    // Keep the handle on this block while its menu is open.
    if (open) editor.commands.lockDragHandle()
    else editor.commands.unlockDragHandle()
  }

  const current = () => {
    const { node, pos } = target.current
    return node && pos >= 0 ? { node, pos } : null
  }

  const addBelow = () => {
    const block = current()
    if (!block) return
    const { node, pos } = block
    if (node.type.name === "paragraph" && node.content.size === 0) {
      editor
        .chain()
        .focus()
        .setTextSelection(pos + 1)
        .insertContent("/")
        .run()
      return
    }
    const after = pos + node.nodeSize
    editor
      .chain()
      .focus()
      .insertContentAt(after, {
        type: "paragraph",
        content: [{ type: "text", text: "/" }],
      })
      .setTextSelection(after + 2)
      .run()
  }

  /** Selects the whole block so a command converts all of it. */
  const selectBlock = (node: PMNode, pos: number) =>
    editor
      .chain()
      .focus()
      .command(({ tr }) => {
        tr.setSelection(
          TextSelection.between(
            tr.doc.resolve(pos + 1),
            tr.doc.resolve(pos + node.nodeSize - 1)
          )
        )
        return true
      })
      .run()

  const turnInto = (id: string) => {
    const block = current()
    const command = BLOCK_COMMANDS.find((c) => c.id === id)
    if (!block || !command) return
    selectBlock(block.node, block.pos)
    command.run(editor, actions)
  }

  const move = (direction: -1 | 1) => {
    const block = current()
    if (!block) return
    const { node, pos } = block
    editor
      .chain()
      .focus()
      .command(({ tr }) => {
        const $pos = tr.doc.resolve(pos)
        const index = $pos.index()
        const sibling = $pos.parent.maybeChild(index + direction)
        if (!sibling) return false
        tr.delete(pos, pos + node.nodeSize)
        const insertAt =
          direction === -1 ? pos - sibling.nodeSize : pos + sibling.nodeSize
        tr.insert(insertAt, node)
        tr.setSelection(TextSelection.near(tr.doc.resolve(insertAt + 1)))
        tr.scrollIntoView()
        return true
      })
      .run()
  }

  const duplicate = () => {
    const block = current()
    if (!block) return
    editor
      .chain()
      .focus()
      .insertContentAt(block.pos + block.node.nodeSize, block.node.toJSON())
      .run()
  }

  const remove = () => {
    const block = current()
    if (!block) return
    editor
      .chain()
      .focus()
      .deleteRange({ from: block.pos, to: block.pos + block.node.nodeSize })
      .run()
  }

  const turnIntoCommands = BLOCK_COMMANDS.filter(
    (command) =>
      TURN_INTO.includes(command.id) &&
      (!command.requires || hasExtension(editor, command.requires))
  )
  const menuNode = menuTarget?.node ?? null
  const index =
    menuTarget && menuTarget.pos >= 0
      ? editor.state.doc.resolve(menuTarget.pos).index()
      : 0
  const siblings = editor.state.doc.childCount

  return (
    <DragHandle
      editor={editor}
      className="drag-handle z-20"
      onNodeChange={({ node, pos }) => {
        target.current = { node, pos }
      }}
    >
      <div className="flex items-center gap-px pr-1.5">
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="Add a block below"
          onClick={addBelow}
          className="text-subtle hover:text-foreground"
        >
          <Icon icon="plus" />
        </Button>
        <div className="relative">
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Drag to move, or click for block options"
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            onClick={() => openMenu(true)}
            className="cursor-grab text-subtle hover:text-foreground active:cursor-grabbing"
          >
            <Icon icon="grip" />
          </Button>
          {/* Anchors the menu, which opens on click rather than on the
              mousedown that starts a drag. */}
          <DropdownMenu open={menuOpen} onOpenChange={openMenu}>
            <DropdownMenuTrigger
              nativeButton={false}
              render={
                <span
                  aria-hidden="true"
                  tabIndex={-1}
                  className="pointer-events-none absolute inset-0"
                />
              }
            />
            <DropdownMenuContent
              side="bottom"
              align="start"
              className="min-w-52"
              finalFocus={() => editor.view.dom as HTMLElement}
            >
              {menuNode && CONVERTIBLE.has(menuNode.type.name) && (
                <>
                  <DropdownMenuSub>
                    <DropdownMenuSubTrigger>
                      <Icon icon="refresh" />
                      Turn into
                    </DropdownMenuSubTrigger>
                    <DropdownMenuSubContent className="min-w-48">
                      {turnIntoCommands.map((command) => (
                        <DropdownMenuItem
                          key={command.id}
                          onClick={() => turnInto(command.id)}
                        >
                          <Icon icon={command.icon} />
                          {command.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuSubContent>
                  </DropdownMenuSub>
                  <DropdownMenuSeparator />
                </>
              )}
              <DropdownMenuGroup>
                <DropdownMenuItem
                  disabled={index === 0}
                  onClick={() => move(-1)}
                >
                  <Icon icon={ArrowUp02Icon} />
                  Move up
                </DropdownMenuItem>
                <DropdownMenuItem
                  disabled={index >= siblings - 1}
                  onClick={() => move(1)}
                >
                  <Icon icon={ArrowDown02Icon} />
                  Move down
                </DropdownMenuItem>
                <DropdownMenuItem onClick={duplicate}>
                  <Icon icon={Copy01Icon} />
                  Duplicate
                </DropdownMenuItem>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive" onClick={remove}>
                <Icon icon={Delete02Icon} />
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </DragHandle>
  )
}

import {
  Delete02Icon,
  DeleteColumnIcon,
  DeleteRowIcon,
  HighlighterIcon,
  InsertColumnLeftIcon,
  InsertColumnRightIcon,
  InsertRowDownIcon,
  InsertRowUpIcon,
  Layout2ColumnIcon,
  Layout2RowIcon,
  SourceCodeIcon,
  TableCellsMergeIcon,
  TableCellsSplitIcon,
  TextBoldIcon,
  TextItalicIcon,
  TextStrikethroughIcon,
  TextUnderlineIcon,
  Unlink02Icon,
} from "@hugeicons/core-free-icons"
import { NodeSelection } from "@tiptap/pm/state"
import { CellSelection } from "@tiptap/pm/tables"
import { useEditorState, type Editor } from "@tiptap/react"
import { BubbleMenu } from "@tiptap/react/menus"
import { cn } from "cn"

import { Icon } from "../icon"
import { hasExtension } from "./commands"
import { ToolbarAction, ToolbarSeparator, ToolbarToggle } from "./controls"
import type { RichTextActions } from "./types"

const MENU =
  "z-30 flex items-center gap-0.5 rounded-(--radius-band) border border-border bg-popover p-1 text-popover-foreground shadow-(--shadow-float)"

type MenuProps = {
  editor: Editor
  actions: RichTextActions
  scrollTarget: HTMLElement
}

/** Formatting for a text selection: marks, highlight and link. */
function TextMenu({ editor, actions, scrollTarget }: MenuProps) {
  const state = useEditorState({
    editor,
    selector: ({ editor }) => ({
      bold: editor.isActive("bold"),
      italic: editor.isActive("italic"),
      underline: editor.isActive("underline"),
      strike: editor.isActive("strike"),
      code: editor.isActive("code"),
      highlight: editor.isActive("highlight"),
      link: editor.isActive("link"),
    }),
  })
  const chain = () => editor.chain().focus()
  const highlight = hasExtension(editor, "highlight")

  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextSelectionMenu"
      className={MENU}
      options={{ placement: "top", offset: 8, scrollTarget }}
      shouldShow={({ editor, state, from, to, view }) => {
        if (!editor.isEditable || from === to || !view.hasFocus()) return false
        const { selection } = state
        if (selection instanceof NodeSelection) return false
        if (selection instanceof CellSelection) return false
        if (editor.isActive("codeBlock")) return false
        return state.doc.textBetween(from, to, " ").trim().length > 0
      }}
    >
      <ToolbarToggle
        icon={TextBoldIcon}
        label="Bold"
        shortcut="Mod-b"
        pressed={state.bold}
        onPressedChange={() => chain().toggleBold().run()}
      />
      <ToolbarToggle
        icon={TextItalicIcon}
        label="Italic"
        shortcut="Mod-i"
        pressed={state.italic}
        onPressedChange={() => chain().toggleItalic().run()}
      />
      <ToolbarToggle
        icon={TextUnderlineIcon}
        label="Underline"
        shortcut="Mod-u"
        pressed={state.underline}
        onPressedChange={() => chain().toggleUnderline().run()}
      />
      <ToolbarToggle
        icon={TextStrikethroughIcon}
        label="Strikethrough"
        shortcut="Mod-Shift-s"
        pressed={state.strike}
        onPressedChange={() => chain().toggleStrike().run()}
      />
      <ToolbarToggle
        icon={SourceCodeIcon}
        label="Inline code"
        shortcut="Mod-e"
        pressed={state.code}
        onPressedChange={() => chain().toggleCode().run()}
      />
      {highlight && (
        <ToolbarToggle
          icon={HighlighterIcon}
          label="Highlight"
          shortcut="Mod-Shift-h"
          pressed={state.highlight}
          onPressedChange={() => chain().toggleHighlight().run()}
        />
      )}
      <ToolbarSeparator />
      <ToolbarToggle
        icon="link"
        label={state.link ? "Edit link" : "Link"}
        shortcut="Mod-k"
        pressed={state.link}
        onPressedChange={() => actions.openDialog({ kind: "link" })}
      />
    </BubbleMenu>
  )
}

/** Shown with the caret in a link: where it goes, edit, copy, remove. */
function LinkMenu({ editor, actions, scrollTarget }: MenuProps) {
  const href = useEditorState({
    editor,
    selector: ({ editor }) =>
      (editor.getAttributes("link").href as string | undefined) ?? "",
  })
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextLinkMenu"
      className={cn(MENU, "max-w-sm")}
      options={{ placement: "bottom-start", offset: 6, scrollTarget }}
      shouldShow={({ editor, from, to, view }) =>
        editor.isEditable &&
        from === to &&
        view.hasFocus() &&
        editor.isActive("link")
      }
    >
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer nofollow"
        className="flex min-w-0 items-center gap-1.5 rounded-(--radius-item) px-1.5 py-1 text-xs text-foreground hover:bg-muted"
      >
        <Icon
          icon="external"
          size={14}
          className="shrink-0 text-muted-foreground"
        />
        <span className="truncate">{href}</span>
      </a>
      <ToolbarSeparator />
      <ToolbarAction
        icon="settings"
        label="Edit link"
        shortcut="Mod-k"
        onClick={() => actions.openDialog({ kind: "link" })}
      />
      <ToolbarAction
        icon="copy"
        label="Copy link"
        onClick={() => void navigator.clipboard.writeText(href)}
      />
      <ToolbarAction
        icon={Unlink02Icon}
        label="Remove link"
        onClick={() =>
          editor.chain().focus().extendMarkRange("link").unsetLink().run()
        }
      />
    </BubbleMenu>
  )
}

/** The table under the caret, found in the DOM for positioning the menu. */
function tableElement(editor: Editor) {
  const { node } = editor.view.domAtPos(editor.state.selection.from)
  const element = node instanceof Element ? node : node.parentElement
  return element?.closest(".tableWrapper") ?? element?.closest("table") ?? null
}

/** Rows, columns, headers and cells of the table under the caret. */
function TableMenu({ editor, scrollTarget }: MenuProps) {
  const can = useEditorState({
    editor,
    selector: ({ editor }) =>
      editor.isDestroyed
        ? { merge: false, split: false, deleteRow: false, deleteColumn: false }
        : {
            merge: editor.can().mergeCells(),
            split: editor.can().splitCell(),
            deleteRow: editor.can().deleteRow(),
            deleteColumn: editor.can().deleteColumn(),
          },
  })
  const chain = () => editor.chain().focus()
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextTableMenu"
      className={MENU}
      options={{ placement: "top-start", offset: 6, scrollTarget }}
      getReferencedVirtualElement={() => {
        const table = tableElement(editor)
        return table
          ? { getBoundingClientRect: () => table.getBoundingClientRect() }
          : null
      }}
      // Out of the way of the selection menu while text is selected.
      shouldShow={({ editor, view, state, from, to }) =>
        editor.isEditable &&
        view.hasFocus() &&
        editor.isActive("table") &&
        (from === to || state.selection instanceof CellSelection)
      }
    >
      <ToolbarAction
        icon={InsertRowUpIcon}
        label="Row above"
        onClick={() => chain().addRowBefore().run()}
      />
      <ToolbarAction
        icon={InsertRowDownIcon}
        label="Row below"
        onClick={() => chain().addRowAfter().run()}
      />
      <ToolbarAction
        icon={DeleteRowIcon}
        label="Delete row"
        disabled={!can.deleteRow}
        onClick={() => chain().deleteRow().run()}
      />
      <ToolbarSeparator />
      <ToolbarAction
        icon={InsertColumnLeftIcon}
        label="Column left"
        onClick={() => chain().addColumnBefore().run()}
      />
      <ToolbarAction
        icon={InsertColumnRightIcon}
        label="Column right"
        onClick={() => chain().addColumnAfter().run()}
      />
      <ToolbarAction
        icon={DeleteColumnIcon}
        label="Delete column"
        disabled={!can.deleteColumn}
        onClick={() => chain().deleteColumn().run()}
      />
      <ToolbarSeparator />
      <ToolbarAction
        icon={TableCellsMergeIcon}
        label="Merge cells"
        disabled={!can.merge}
        onClick={() => chain().mergeCells().run()}
      />
      <ToolbarAction
        icon={TableCellsSplitIcon}
        label="Split cell"
        disabled={!can.split}
        onClick={() => chain().splitCell().run()}
      />
      <ToolbarAction
        icon={Layout2RowIcon}
        label="Header row"
        onClick={() => chain().toggleHeaderRow().run()}
      />
      <ToolbarAction
        icon={Layout2ColumnIcon}
        label="Header column"
        onClick={() => chain().toggleHeaderColumn().run()}
      />
      <ToolbarSeparator />
      <ToolbarAction
        icon={Delete02Icon}
        label="Delete table"
        onClick={() => chain().deleteTable().run()}
        className="hover:bg-destructive/10 hover:text-destructive"
      />
    </BubbleMenu>
  )
}

/** A selected image: alt text, original size, open, delete. */
function ImageMenu({ editor, actions, scrollTarget }: MenuProps) {
  const image = useEditorState({
    editor,
    selector: ({ editor }) => ({
      src: (editor.getAttributes("image").src as string | undefined) ?? "",
      resized: Boolean(editor.getAttributes("image").width),
    }),
  })
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextImageMenu"
      className={MENU}
      options={{ placement: "top", offset: 8, scrollTarget }}
      shouldShow={({ editor, state }) =>
        editor.isEditable &&
        state.selection instanceof NodeSelection &&
        state.selection.node.type.name === "image"
      }
    >
      <ToolbarAction
        icon="settings"
        label="Alt text and source"
        onClick={() =>
          actions.openDialog({
            kind: "image",
            pos: editor.state.selection.from,
          })
        }
      />
      <ToolbarAction
        icon="refresh"
        label="Original size"
        disabled={!image.resized}
        onClick={() =>
          editor
            .chain()
            .focus()
            .updateAttributes("image", { width: null, height: null })
            .run()
        }
      />
      {!image.src.startsWith("data:") && (
        <ToolbarAction
          icon="external"
          label="Open image"
          onClick={() =>
            window.open(image.src, "_blank", "noopener,noreferrer")
          }
        />
      )}
      <ToolbarSeparator />
      <ToolbarAction
        icon={Delete02Icon}
        label="Delete image"
        onClick={() => editor.chain().focus().deleteSelection().run()}
        className="hover:bg-destructive/10 hover:text-destructive"
      />
    </BubbleMenu>
  )
}

/** Every contextual menu the editor shows, for the features it has. */
export function RichTextBubbleMenus(props: MenuProps) {
  const { editor } = props
  return (
    <>
      <TextMenu {...props} />
      <LinkMenu {...props} />
      {hasExtension(editor, "table") && <TableMenu {...props} />}
      {hasExtension(editor, "image") && <ImageMenu {...props} />}
    </>
  )
}

import type { Editor, JSONContent } from "@tiptap/react"
// Brings in the Markdown extension's `getMarkdown` and `contentType` types.
import type {} from "@tiptap/markdown"

import type { RichTextFormat, RichTextValue } from "./types"

/**
 * Reads the document in `format`. An empty document is `""` in HTML and
 * Markdown, so required-field checks can test the string.
 */
export function readContent(editor: Editor, format: "json"): JSONContent
export function readContent(
  editor: Editor,
  format: RichTextFormat
): RichTextValue
export function readContent(
  editor: Editor,
  format: RichTextFormat
): RichTextValue {
  if (format === "json") return editor.getJSON()
  if (editor.isEmpty) return ""
  return format === "markdown" ? editor.getMarkdown() : editor.getHTML()
}

/** Replaces the document without firing `onUpdate`. */
export function writeContent(
  editor: Editor,
  value: RichTextValue | null | undefined,
  format: RichTextFormat
) {
  editor.commands.setContent(value ?? "", {
    emitUpdate: false,
    contentType: typeof value === "string" ? format : "json",
  })
}

/** Whether two values hold the same content, to skip redundant resets. */
export function sameContent(
  a: RichTextValue | null | undefined,
  b: RichTextValue | null | undefined
) {
  if (a === b) return true
  if (a == null || b == null) return (a ?? "") === (b ?? "")
  if (typeof a === "string" || typeof b === "string") return false
  return JSON.stringify(a) === JSON.stringify(b)
}

/** Saves `text` as a file the person downloads. */
export function downloadText(text: string, filename: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const link = document.createElement("a")
  link.href = url
  link.download = filename
  link.click()
  // Revoking in the same task can cancel the download in some browsers.
  setTimeout(() => URL.revokeObjectURL(url), 0)
}

import * as React from "react"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Kbd } from "@/components/ui/kbd"
import { PopoverTrigger } from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { Toggle } from "@/components/ui/toggle"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { Icon } from "../icon"
import type { IconProp } from "../icons"
import type { Swatch } from "./palette"
import { formatShortcut } from "./shortcuts"

function Hint({ label, shortcut }: { label: string; shortcut?: string }) {
  return (
    <TooltipContent side="bottom">
      {label}
      {shortcut && <Kbd>{formatShortcut(shortcut)}</Kbd>}
    </TooltipContent>
  )
}

/** An on/off formatting button (bold, bulleted list, …) with its shortcut. */
export function ToolbarToggle({
  icon,
  label,
  shortcut,
  pressed,
  disabled,
  onPressedChange,
}: {
  icon: IconProp
  label: string
  shortcut?: string
  pressed: boolean
  disabled?: boolean
  onPressedChange: () => void
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Toggle
            size="sm"
            aria-label={label}
            pressed={pressed}
            disabled={disabled}
            onPressedChange={onPressedChange}
            className="min-w-7 px-1.5 text-muted-foreground aria-pressed:text-foreground"
          />
        }
      >
        <Icon icon={icon} />
      </TooltipTrigger>
      <Hint label={label} shortcut={shortcut} />
    </Tooltip>
  )
}

/** A one-shot action (undo, clear formatting, …). */
export function ToolbarAction({
  icon,
  label,
  shortcut,
  disabled,
  onClick,
  className,
}: {
  icon: IconProp
  label: string
  shortcut?: string
  disabled?: boolean
  onClick: () => void
  className?: string
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label={label}
            disabled={disabled}
            onClick={onClick}
            className={cn("text-muted-foreground", className)}
          />
        }
      >
        <Icon icon={icon} />
      </TooltipTrigger>
      <Hint label={label} shortcut={shortcut} />
    </Tooltip>
  )
}

/**
 * The trigger of a toolbar dropdown: an icon (or a short text value) and a
 * caret, with a tooltip. Render it inside `<DropdownMenu>`, or inside
 * `<Popover>` with `popover` for panels that hold plain buttons.
 */
export function ToolbarMenuTrigger({
  icon,
  label,
  value,
  disabled,
  active,
  popover = false,
  className,
  children,
}: {
  icon?: IconProp
  label: string
  value?: React.ReactNode
  disabled?: boolean
  active?: boolean
  popover?: boolean
  className?: string
  children?: React.ReactNode
}) {
  const Trigger = popover ? PopoverTrigger : DropdownMenuTrigger
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Trigger
            render={
              <Button
                type="button"
                variant="ghost"
                size="sm"
                aria-label={label}
                disabled={disabled}
                data-active={active || undefined}
                className={cn(
                  "gap-0.5 px-1.5 font-normal text-muted-foreground data-popup-open:bg-muted data-popup-open:text-foreground data-active:bg-muted data-active:text-foreground",
                  className
                )}
              />
            }
          />
        }
      >
        {icon && <Icon icon={icon} />}
        {value !== undefined && (
          <span className="truncate text-xs text-foreground">{value}</span>
        )}
        {children}
        <Icon icon="down" className="size-3 opacity-60" />
      </TooltipTrigger>
      <Hint label={label} />
    </Tooltip>
  )
}

export function ToolbarSeparator() {
  return (
    <Separator
      orientation="vertical"
      className="mx-0.5 h-4 self-center data-vertical:self-center"
    />
  )
}

/**
 * A row of colour swatches. Text colours show an "A" in the colour;
 * highlights show the fill. The chosen one is marked.
 */
export function SwatchGrid({
  label,
  swatches,
  kind,
  current,
  onSelect,
}: {
  label: string
  swatches: Swatch[]
  kind: "text" | "highlight"
  current: string | null
  onSelect: (value: string | null) => void
}) {
  return (
    <div
      role="group"
      aria-label={label}
      className="grid grid-cols-9 gap-1 px-1.5 pb-1.5"
    >
      {swatches.map((swatch) => {
        const selected = (current ?? null) === swatch.value
        return (
          <Tooltip key={swatch.name}>
            <TooltipTrigger
              render={
                <button
                  type="button"
                  aria-label={`${label}: ${swatch.name}`}
                  aria-pressed={selected}
                  onClick={() => onSelect(swatch.value)}
                  className="grid size-6 place-items-center overflow-hidden rounded-(--radius-item) border border-border text-xs font-semibold transition-shadow hover:shadow-(--shadow-raised) aria-pressed:border-foreground"
                  style={
                    swatch.value === null
                      ? undefined
                      : kind === "text"
                        ? { color: swatch.value }
                        : { background: swatch.value }
                  }
                />
              }
            >
              {swatch.value === null ? (
                <span
                  aria-hidden="true"
                  className="h-px w-8 -rotate-45 bg-muted-foreground/60"
                />
              ) : kind === "text" ? (
                "A"
              ) : null}
            </TooltipTrigger>
            <TooltipContent side="bottom">{swatch.name}</TooltipContent>
          </Tooltip>
        )
      })}
    </div>
  )
}

