/**
 * Callbacks the extensions call into the component with. The object is
 * stable and reads the latest props itself, so the editor never rebuilds
 * for a new callback.
 */
export interface EditorHandlers {
  actions: RichTextActions
  insertFiles: (editor: Editor, files: File[], pos?: number) => void
  isEditable: () => boolean
  placeholder: () => string
  mentions: MentionSource
  isFullscreen: () => boolean
}

export interface ExtensionConfig {
  features: RichTextFeatures
  maxLength?: number
  /** Whether `@` suggests people (the source itself comes from handlers). */
  mentions: boolean
  handlers: EditorHandlers
}

/**
 * Editor-level keys: ⌘K links, ⌘F finds, ⌘⇧Enter toggles full screen and
 * Escape leaves it. Low priority, so open suggestion menus get Escape first.
 */
const Shortcuts = Extension.create<{
  handlers: EditorHandlers
  features: RichTextFeatures
}>({
  name: "richTextShortcuts",
  priority: 10,

  addKeyboardShortcuts() {
    const { handlers, features } = this.options
    const { actions } = handlers
    return {
      "Mod-k": ({ editor }) => {
        if (!editor.isEditable || editor.isActive("codeBlock")) return false
        actions.openDialog({ kind: "link" })
        return true
      },
      "Mod-f": () => {
        if (!features.findReplace) return false
        actions.toggleFind(true)
        return true
      },
      "Mod-Shift-Enter": () => {
        if (!features.fullscreen) return false
        actions.toggleFullscreen()
        return true
      },
      Escape: () => {
        if (!handlers.isFullscreen()) return false
        actions.toggleFullscreen(false)
        return true
      },
    }
  },
})

function emojiItems(emojis: EmojiItem[], query: string) {
  const q = query.toLowerCase()
  return emojis
    .filter(
      ({ shortcodes, tags }) =>
        shortcodes.some((code) => code.startsWith(q)) ||
        tags.some((tag) => tag.startsWith(q))
    )
    .slice(0, 8)
}

/** Every extension the editor loads, trimmed to the enabled features. */
export function createExtensions({
  features,
  maxLength,
  mentions,
  handlers,
}: ExtensionConfig): AnyExtension[] {
  const extensions: AnyExtension[] = [
    Shortcuts.configure({ handlers, features }),
    StarterKit.configure({
      heading: features.headings ? { levels: [1, 2, 3, 4, 5, 6] } : false,
      // Replaced by the highlighted code block below when that's on.
      codeBlock: features.codeHighlighting ? false : {},
      link: {
        openOnClick: false,
        autolink: true,
        linkOnPaste: true,
        defaultProtocol: "https",
      },
      dropcursor: { color: "var(--focus)", width: 2 },
      undoRedo: { depth: 200 },
    }),
    Placeholder.configure({
      includeChildren: true,
      placeholder: ({ editor, node }) => {
        if (node.type.name === "heading") return `Heading ${node.attrs.level}`
        if (node.type.name === "detailsSummary") return "Summary"
        if (editor.isEmpty) return handlers.placeholder()
        return features.slashCommands ? "Type / for commands" : ""
      },
    }),
    CharacterCount.configure({ limit: maxLength ?? null }),
    Focus.configure({ className: "has-focus", mode: "shallowest" }),
    Selection.configure({ className: "selection" }),
    Markdown,
    MarkdownPaste,
  ]

  if (features.textStyle) {
    extensions.push(TextStyleKit, Highlight.configure({ multicolor: true }))
  }
  if (features.alignment) {
    extensions.push(TextAlign.configure({ types: ["heading", "paragraph"] }))
  }
  if (features.scripts) extensions.push(Subscript, Superscript)
  if (features.typography) extensions.push(Typography)
  if (features.taskLists) {
    extensions.push(TaskList, TaskItem.configure({ nested: true }))
  }
  if (features.tables) {
    extensions.push(TableKit.configure({ table: { resizable: true } }))
  }
  if (features.codeHighlighting) {
    extensions.push(
      CodeBlockLowlight.extend({
        addNodeView: () => ReactNodeViewRenderer(CodeBlockView),
      }).configure({ lowlight, enableTabIndentation: true, tabSize: 2 })
    )
  }
  if (features.images) {
    extensions.push(
      Image.configure({
        allowBase64: true,
        resize: {
          enabled: true,
          directions: ["top-left", "top-right", "bottom-left", "bottom-right"],
          minWidth: 48,
          minHeight: 48,
          alwaysPreserveAspectRatio: true,
        },
      })
    )
  }
  if (features.media) {
    extensions.push(
      Youtube.configure({ nocookie: true, width: 640, height: 360 }),
      Twitch.configure({ width: 640, height: 360 }),
      Audio.configure({ allowBase64: true, controls: true })
    )
  }
  if (features.images || features.media) {
    const allowedMimeTypes = [
      ...(features.images ? IMAGE_TYPES : []),
      ...(features.media ? AUDIO_TYPES : []),
    ]
    extensions.push(
      FileHandler.configure({
        allowedMimeTypes,
        onDrop: (editor, files, pos) =>
          handlers.insertFiles(editor, files, pos),
        // A copy that also carries HTML (an image copied from a web page)
        // pastes through the HTML; only bare files are inserted here.
        onPaste: (editor, files, html) => {
          if (!html) handlers.insertFiles(editor, files)
        },
      })
    )
  }
  if (features.math) {
    const edit =
      (kind: "inlineMath" | "blockMath") =>
      (node: { attrs: Record<string, unknown> }, pos: number) => {
        if (!handlers.isEditable()) return
        handlers.actions.openDialog({
          kind,
          pos,
          initial: String(node.attrs.latex ?? ""),
        })
      }
    // Configured apart, so blocks render in KaTeX display mode.
    extensions.push(
      InlineMath.configure({
        katexOptions: { throwOnError: false },
        onClick: edit("inlineMath"),
      }),
      BlockMath.configure({
        katexOptions: { throwOnError: false, displayMode: true },
        onClick: edit("blockMath"),
      })
    )
  }
  if (features.details) {
    extensions.push(
      Details.configure({
        persist: true,
        HTMLAttributes: { class: "details" },
      }),
      DetailsSummary,
      DetailsContent
    )
  }
  if (features.emoji) {
    extensions.push(
      Emoji.configure({
        emojis: gitHubEmojis,
        enableEmoticons: true,
        suggestion: {
          items: ({ editor, query }) =>
            emojiItems(editor.storage.emoji.emojis, query),
          render: suggestionRenderer<EmojiItem>({
            label: "Emoji",
            empty: "No matching emoji",
            getKey: (item) => item.name,
            renderItem: (item) => (
              <>
                <span className="grid w-5 place-items-center text-base leading-none">
                  {item.emoji ??
                    (item.fallbackImage && (
                      <img src={item.fallbackImage} alt="" className="size-4" />
                    ))}
                </span>
                <span className="truncate">:{item.shortcodes[0]}:</span>
              </>
            ),
          }),
        },
      })
    )
  }
  if (mentions) {
    extensions.push(
      Mention.configure({
        HTMLAttributes: { class: "mention" },
        deleteTriggerWithBackspace: true,
        suggestion: {
          debounce: 150,
          items: ({ query, signal }) => handlers.mentions(query, signal),
          render: suggestionRenderer<MentionItem>({
            label: "People",
            empty: "No one matches",
            getKey: (item) => item.id,
            renderItem: (item) => (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{item.label}</span>
                {item.description && (
                  <span className="truncate text-2xs text-muted-foreground">
                    {item.description}
                  </span>
                )}
              </span>
            ),
          }),
        },
      })
    )
  }
  if (features.slashCommands) {
    extensions.push(
      SlashCommand.configure({ getActions: () => handlers.actions })
    )
  }
  if (features.findReplace) {
    extensions.push(FindAndReplace.configure({ injectCSS: false }))
  }
  if (features.invisibleCharacters) {
    extensions.push(InvisibleCharacters.configure({ visible: false }))
  }
  if (features.uniqueIds) {
    extensions.push(
      UniqueID.configure({ attributeName: "data-id", types: "all" })
    )
  }
  return extensions
}

import type { Editor, JSONContent } from "@tiptap/react"

import type { UploadHandler } from "./types"

export const IMAGE_TYPES = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
  "image/avif",
  "image/svg+xml",
]

export const AUDIO_TYPES = [
  "audio/mpeg",
  "audio/mp4",
  "audio/aac",
  "audio/ogg",
  "audio/wav",
  "audio/webm",
  "audio/flac",
]

function readAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result))
    reader.onerror = () => reject(reader.error ?? new Error("Unreadable file"))
    reader.readAsDataURL(file)
  })
}

function formatBytes(bytes: number) {
  if (bytes >= 1024 * 1024) return `${Math.round(bytes / 1024 / 1024)} MB`
  return `${Math.round(bytes / 1024)} KB`
}

function nodeFor(file: File, src: string): JSONContent | null {
  if (file.type.startsWith("image/")) {
    return { type: "image", attrs: { src, alt: file.name } }
  }
  if (file.type.startsWith("audio/")) return { type: "audio", attrs: { src } }
  return null
}

/**
 * Uploads (or inlines) each image and audio file and inserts it at `pos`, or
 * at the selection. Files the editor can't hold are reported, not dropped
 * silently.
 */
export async function insertFiles(
  editor: Editor,
  files: File[],
  {
    upload,
    maxFileSize,
    pos,
    onError,
  }: {
    upload?: UploadHandler
    maxFileSize: number
    pos?: number
    onError: (message: string) => void
  }
) {
  let at = pos
  for (const file of files) {
    const supported =
      (file.type.startsWith("image/") && editor.schema.nodes.image) ||
      (file.type.startsWith("audio/") && editor.schema.nodes.audio)
    if (!supported) {
      onError(`${file.name} isn't an image or audio file this editor accepts.`)
      continue
    }
    if (file.size > maxFileSize) {
      onError(`${file.name} is over the ${formatBytes(maxFileSize)} limit.`)
      continue
    }
    try {
      const src = upload ? await upload(file) : await readAsDataUrl(file)
      if (editor.isDestroyed) return
      const node = nodeFor(file, src)
      if (!node) continue
      if (at === undefined) {
        editor.chain().focus().insertContent(node).run()
      } else {
        // The document may have changed while the upload ran.
        at = Math.min(at, editor.state.doc.content.size)
        editor.chain().insertContentAt(at, node).focus().run()
        at = editor.state.selection.to
      }
    } catch (error) {
      onError(
        `${file.name} couldn't be added: ${error instanceof Error ? error.message : String(error)}`
      )
    }
  }
}

import * as React from "react"
import {
  CaseSensitiveIcon,
  RegexIcon,
  ReplaceAllIcon,
  ReplaceIcon,
  WholeWordIcon,
} from "@hugeicons/core-free-icons"
import { useEditorState, type Editor } from "@tiptap/react"

import { Input } from "@/components/ui/input"
import { ToolbarAction, ToolbarToggle } from "./controls"

/**
 * ⌘F search over the document: matches highlight as you type, Enter and
 * ⇧Enter step through them, and Replace swaps the current one or all.
 */
export function FindReplaceBar({
  editor,
  onClose,
}: {
  editor: Editor
  onClose: () => void
}) {
  const search = useEditorState({
    editor,
    selector: ({ editor }) => {
      const storage = editor.storage.findAndReplace
      if (!storage) return null
      return {
        total: storage.results.length,
        current: storage.currentIndex,
        caseSensitive: storage.caseSensitive,
        useRegex: storage.useRegex,
        wholeWord: storage.wholeWord,
      }
    },
  })
  // Searching the selected text is the usual way in.
  const [initialTerm] = React.useState(() => {
    const { from, to, empty } = editor.state.selection
    const selected = empty ? "" : editor.state.doc.textBetween(from, to, " ")
    return selected && !selected.includes("\n") && selected.length < 200
      ? selected
      : (editor.storage.findAndReplace?.searchTerm ?? "")
  })
  const [term, setTerm] = React.useState(initialTerm)
  const [replacement, setReplacement] = React.useState(
    () => editor.storage.findAndReplace?.replaceTerm ?? ""
  )
  const findRef = React.useRef<HTMLInputElement>(null)
  const readOnly = !editor.isEditable

  React.useEffect(() => {
    if (initialTerm) editor.commands.setSearchTerm(initialTerm)
    findRef.current?.focus()
    findRef.current?.select()
  }, [editor, initialTerm])

  if (!search) return null

  const close = () => {
    editor.commands.clearSearch()
    onClose()
    editor.commands.focus()
  }

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault()
      close()
    }
  }

  const count = !term
    ? ""
    : search.total === 0
      ? "No results"
      : `${search.current === null ? "–" : search.current + 1} of ${search.total}`

  return (
    <div
      role="search"
      aria-label="Find and replace"
      data-slot="rich-text-find"
      onKeyDown={onKeyDown}
      className="flex flex-wrap items-center gap-x-2 gap-y-1 border-b border-border bg-muted/40 px-2 py-1.5"
    >
      <div className="flex min-w-56 flex-1 items-center gap-0.5">
        <Input
          ref={findRef}
          aria-label="Find"
          placeholder="Find"
          value={term}
          onChange={(event) => {
            setTerm(event.target.value)
            editor.commands.setSearchTerm(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key !== "Enter") return
            event.preventDefault()
            if (event.shiftKey) editor.commands.goToPreviousResult()
            else editor.commands.goToNextResult()
          }}
          className="h-7 min-w-0 flex-1 text-xs md:text-xs"
        />
        <span
          aria-live="polite"
          className="w-[4.5rem] shrink-0 text-center text-2xs text-muted-foreground tabular-nums"
        >
          {count}
        </span>
        <ToolbarToggle
          icon={CaseSensitiveIcon}
          label="Match case"
          pressed={search.caseSensitive}
          onPressedChange={() =>
            editor.commands.setCaseSensitive(!search.caseSensitive)
          }
        />
        <ToolbarToggle
          icon={WholeWordIcon}
          label="Whole words"
          pressed={search.wholeWord}
          onPressedChange={() =>
            editor.commands.setWholeWord(!search.wholeWord)
          }
        />
        <ToolbarToggle
          icon={RegexIcon}
          label="Regular expression"
          pressed={search.useRegex}
          onPressedChange={() => editor.commands.setUseRegex(!search.useRegex)}
        />
        <ToolbarAction
          icon="up"
          label="Previous match"
          shortcut="Shift-Enter"
          disabled={!search.total}
          onClick={() => editor.commands.goToPreviousResult()}
        />
        <ToolbarAction
          icon="down"
          label="Next match"
          shortcut="Enter"
          disabled={!search.total}
          onClick={() => editor.commands.goToNextResult()}
        />
      </div>
      {!readOnly && (
        <div className="flex min-w-56 flex-1 items-center gap-0.5">
          <Input
            aria-label="Replace with"
            placeholder="Replace with"
            value={replacement}
            onChange={(event) => {
              setReplacement(event.target.value)
              editor.commands.setReplaceTerm(event.target.value)
            }}
            onKeyDown={(event) => {
              if (event.key !== "Enter") return
              event.preventDefault()
              if (event.metaKey || event.ctrlKey) editor.commands.replaceAll()
              else editor.commands.replace()
            }}
            className="h-7 min-w-0 flex-1 text-xs md:text-xs"
          />
          <ToolbarAction
            icon={ReplaceIcon}
            label="Replace"
            shortcut="Enter"
            disabled={!search.total}
            onClick={() => editor.commands.replace()}
          />
          <ToolbarAction
            icon={ReplaceAllIcon}
            label="Replace all"
            shortcut="Mod-Enter"
            disabled={!search.total}
            onClick={() => editor.commands.replaceAll()}
          />
        </div>
      )}
      <ToolbarAction
        icon="close"
        label="Close"
        shortcut="Escape"
        onClick={close}
      />
    </div>
  )
}

