/** Adds `https://` to bare domains; leaves mailto:, tel:, # and / links. */
function normalizeHref(value: string) {
  const href = value.trim()
  if (!href) return ""
  if (/^([a-z][a-z\d+.-]*:|#|\/)/i.test(href)) return href
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(href)) return `mailto:${href}`
  return `https://${href}`
}

function isHttpUrl(value: string) {
  try {
    return ["http:", "https:"].includes(new URL(value).protocol)
  } catch {
    return false
  }
}

function initialValues(editor: Editor, request: InsertDialogRequest) {
  const { from, to, empty } = editor.state.selection
  switch (request.kind) {
    case "link":
      return {
        value: (editor.getAttributes("link").href as string | undefined) ?? "",
        text: empty ? "" : editor.state.doc.textBetween(from, to, " "),
      }
    case "image":
      if (request.pos === undefined) return { value: "", text: "" }
      return {
        value: (editor.getAttributes("image").src as string | undefined) ?? "",
        text: (editor.getAttributes("image").alt as string | undefined) ?? "",
      }
    default:
      return { value: request.initial ?? "", text: "" }
  }
}

/**
 * The one dialog behind every insert that needs input: links, images,
 * embeds, audio and formulas. Saving writes to the editor and returns focus
 * to where the caret was.
 */
export function InsertDialog({
  editor,
  request,
  actions,
  onClose,
}: {
  editor: Editor
  request: InsertDialogRequest | null
  actions: RichTextActions
  onClose: () => void
}) {
  // Keep the last request while the dialog animates closed.
  const [shown, setShown] = React.useState(request)
  if (request && request !== shown) setShown(request)
  const kind = shown?.kind ?? "link"
  const copy = COPY[kind]
  const editing =
    shown?.pos !== undefined || (kind === "link" && editor.isActive("link"))

  const [value, setValue] = React.useState("")
  const [text, setText] = React.useState("")
  const [error, setError] = React.useState<string | null>(null)
  const [openedFor, setOpenedFor] = React.useState<InsertDialogRequest | null>(
    null
  )
  if (request && request !== openedFor) {
    const initial = initialValues(editor, request)
    setOpenedFor(request)
    setValue(initial.value)
    setText(initial.text)
    setError(null)
  }

  const isMath = kind === "inlineMath" || kind === "blockMath"
  const preview = React.useMemo(
    () =>
      isMath && value.trim()
        ? katex.renderToString(value, {
            throwOnError: false,
            displayMode: kind === "blockMath",
          })
        : "",
    [isMath, kind, value]
  )

  const pos = shown?.pos
  const id = React.useId()
  const chain = () => editor.chain().focus()

  const save = (): string | null => {
    const input = value.trim()
    switch (kind) {
      case "link": {
        const href = normalizeHref(input)
        if (!href) {
          chain().extendMarkRange("link").unsetLink().run()
          return null
        }
        if (editor.state.selection.empty && !editor.isActive("link")) {
          return chain()
            .insertContent({
              type: "text",
              text: text.trim() || href,
              marks: [{ type: "link", attrs: { href } }],
            })
            .run()
            ? null
            : "That link isn't allowed."
        }
        return chain().extendMarkRange("link").setLink({ href }).run()
          ? null
          : "That link isn't allowed."
      }
      case "image": {
        if (!isHttpUrl(input) && !input.startsWith("data:image/")) {
          return "Enter an http or https address."
        }
        const alt = text.trim() || null
        if (pos !== undefined) {
          chain()
            .setNodeSelection(pos)
            .updateAttributes("image", { src: input, alt })
            .run()
        } else
          chain()
            .setImage({ src: input, alt: alt ?? undefined })
            .run()
        return null
      }
      case "youtube":
        if (!isValidYoutubeUrl(input)) return "That isn't a YouTube link."
        chain().setYoutubeVideo({ src: input }).run()
        return null
      case "twitch":
        if (!isValidTwitchUrl(input)) return "That isn't a Twitch link."
        chain().setTwitchVideo({ src: input }).run()
        return null
      case "audio":
        if (!isHttpUrl(input)) return "Enter an http or https address."
        chain().setAudio({ src: input }).run()
        return null
      case "inlineMath":
        if (pos !== undefined) {
          if (!input) chain().deleteInlineMath({ pos }).run()
          else chain().updateInlineMath({ latex: input, pos }).run()
        } else if (input) chain().insertInlineMath({ latex: input }).run()
        return null
      case "blockMath":
        if (pos !== undefined) {
          if (!input) chain().deleteBlockMath({ pos }).run()
          else chain().updateBlockMath({ latex: input, pos }).run()
        } else if (input) chain().insertBlockMath({ latex: input }).run()
        return null
    }
  }

  const submit = (event: { preventDefault: () => void }) => {
    event.preventDefault()
    const problem = save()
    if (problem) setError(problem)
    else onClose()
  }

  const upload = kind === "image" || kind === "audio" ? kind : null
  const showText =
    kind === "link" && editor.state.selection.empty && !editor.isActive("link")
  const showAlt = kind === "image"

  return (
    <Dialog open={request !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        className="sm:max-w-md"
        finalFocus={() => editor.view.dom as HTMLElement}
      >
        <form onSubmit={submit} className="grid gap-5" noValidate>
          <DialogHeader>
            <DialogTitle>
              {editing ? `Edit ${copy.title.toLowerCase()}` : copy.title}
            </DialogTitle>
            <DialogDescription>{copy.description}</DialogDescription>
          </DialogHeader>

          <FieldGroup>
            {upload && pos === undefined && (
              <>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    onClose()
                    actions.pickFiles(upload)
                  }}
                >
                  <Icon icon={Upload01Icon} data-icon="inline-start" />
                  Upload {upload === "image" ? "an image" : "an audio file"}
                </Button>
                <div className="flex items-center gap-3 text-2xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border">
                  or link one
                </div>
              </>
            )}
            <Field data-invalid={Boolean(error)}>
              <FieldLabel htmlFor={`${id}-value`}>{copy.field}</FieldLabel>
              {isMath ? (
                <Textarea
                  id={`${id}-value`}
                  value={value}
                  placeholder={copy.placeholder}
                  spellCheck={false}
                  aria-invalid={Boolean(error)}
                  onChange={(event) => setValue(event.target.value)}
                  onKeyDown={(event) => {
                    if (
                      event.key === "Enter" &&
                      (event.metaKey || event.ctrlKey)
                    ) {
                      submit(event)
                    }
                  }}
                  className="min-h-20 font-mono text-xs"
                />
              ) : (
                <Input
                  id={`${id}-value`}
                  value={value}
                  placeholder={copy.placeholder}
                  type={kind === "link" ? "text" : "url"}
                  inputMode="url"
                  autoComplete="off"
                  spellCheck={false}
                  aria-invalid={Boolean(error)}
                  onChange={(event) => {
                    setValue(event.target.value)
                    setError(null)
                  }}
                />
              )}
              {isMath && (
                <FieldDescription>
                  {formatShortcut("Mod-Enter")} saves.
                  {pos !== undefined &&
                    " Leave it empty to remove the formula."}
                </FieldDescription>
              )}
              {kind === "link" && editing && (
                <FieldDescription>
                  Leave it empty to remove the link.
                </FieldDescription>
              )}
              {error && <FieldError>{error}</FieldError>}
            </Field>
            {(showText || showAlt) && (
              <Field>
                <FieldLabel htmlFor={`${id}-text`}>
                  {showAlt ? "Alt text" : "Text to show"}
                </FieldLabel>
                <Input
                  id={`${id}-text`}
                  value={text}
                  placeholder={
                    showAlt ? "What the image shows" : "Defaults to the URL"
                  }
                  onChange={(event) => setText(event.target.value)}
                />
                {showAlt && (
                  <FieldDescription>
                    Read aloud by screen readers and shown if the image can't
                    load.
                  </FieldDescription>
                )}
              </Field>
            )}
            {isMath && (
              <div
                aria-label="Preview"
                className="grid min-h-14 place-items-center overflow-x-auto rounded-(--radius-card) border border-border bg-muted/40 px-3 py-2 text-sm"
              >
                {preview ? (
                  <span dangerouslySetInnerHTML={{ __html: preview }} />
                ) : (
                  <span className="text-xs text-subtle">Preview</span>
                )}
              </div>
            )}
          </FieldGroup>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">{editing ? "Save" : "Insert"}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

import * as React from "react"
import { cn } from "cn"

import { Skeleton } from "@/components/ui/skeleton"
import type { RichTextEditorProps } from "./rich-text-editor"

// Tiptap, KaTeX, the emoji set and the syntax grammars come to ~500 kB
// gzipped, so the editor loads with the first field that shows it, not with
// every page that could.
const load = () => import("./rich-text-editor")
const Editor = React.lazy(() =>
  load().then((module) => ({ default: module.RichTextEditor }))
)
const View = React.lazy(() =>
  load().then((module) => ({ default: module.RichTextView }))
)

function EditorSkeleton({
  className,
  toolbar,
}: {
  className?: string
  toolbar: boolean
}) {
  return (
    <div
      aria-busy="true"
      aria-label="Loading editor"
      className={cn(
        "flex flex-col rounded-(--radius-control) border border-border bg-background",
        className
      )}
    >
      {toolbar && (
        <div className="flex items-center gap-1.5 border-b border-border px-2 py-2">
          <Skeleton className="h-5 w-12" />
          <Skeleton className="h-5 w-24" />
          <Skeleton className="h-5 w-40" />
        </div>
      )}
      <div className="flex min-h-32 flex-col gap-2 px-4 py-3">
        <Skeleton className="h-4 w-2/3" />
        <Skeleton className="h-4 w-1/2" />
      </div>
    </div>
  )
}

/**
 * A complete rich text field on Tiptap. See `rich-text-editor.tsx` for the
 * props; this wrapper loads the editor on first render and shows a field
 * skeleton meanwhile.
 */
export function RichTextEditor(props: RichTextEditorProps) {
  const readOnly = Boolean(props.readOnly || props.disabled)
  return (
    <React.Suspense
      fallback={
        <EditorSkeleton
          className={props.className}
          toolbar={props.toolbar ?? !readOnly}
        />
      }
    >
      <Editor {...props} />
    </React.Suspense>
  )
}

/** Saved rich text, shown read-only; loads the editor like `RichTextEditor`. */
export function RichTextView(props: React.ComponentProps<typeof View>) {
  return (
    <React.Suspense
      fallback={
        <div aria-busy="true" className="flex flex-col gap-2">
          <Skeleton className="h-4 w-2/3" />
          <Skeleton className="h-4 w-1/2" />
        </div>
      }
    >
      <View {...props} />
    </React.Suspense>
  )
}

import dockerfile from "highlight.js/lib/languages/dockerfile"
import { common, createLowlight } from "lowlight"

/** Highlight.js grammars for code blocks: the common set plus Dockerfiles. */
export const lowlight = createLowlight({ ...common, dockerfile })

import { Extension } from "@tiptap/core"
import { Plugin, PluginKey } from "@tiptap/pm/state"

// Block syntax at a line start, or inline bold, links and code spans.
const MARKDOWN_HINT =
  /^(?:#{1,6}\s|[-*+]\s|\d+[.)]\s|>\s|```|\|.*\|\s*$|- \[[ x]\]\s)|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\([^)\s]+\)|`[^`\n]+`/m

/**
 * Pasting plain text that looks like Markdown (from an editor, a terminal or
 * a chat) converts it to rich content. Copies that carry HTML paste as HTML,
 * and code blocks keep the text as typed.
 */
export const MarkdownPaste = Extension.create({
  name: "markdownPaste",

  addProseMirrorPlugins() {
    const editor = this.editor
    return [
      new Plugin({
        key: new PluginKey("markdownPaste"),
        props: {
          handlePaste: (_view, event) => {
            const data = event.clipboardData
            if (
              !data ||
              data.files.length ||
              data.types.includes("text/html")
            ) {
              return false
            }
            const text = data.getData("text/plain")
            if (!text || !MARKDOWN_HINT.test(text)) return false
            if (editor.isActive("codeBlock") || editor.isActive("code")) {
              return false
            }
            return editor.commands.insertContent(text, {
              contentType: "markdown",
            })
          },
        },
      }),
    ]
  },
})

import { TextSelection } from "@tiptap/pm/state"
import { useEditorState, type Editor } from "@tiptap/react"
import { cn } from "cn"

interface Heading {
  pos: number
  level: number
  text: string
}

function readHeadings(editor: Editor) {
  const headings: Heading[] = []
  editor.state.doc.descendants((node, pos) => {
    if (node.type.name !== "heading") return node.isBlock
    headings.push({
      pos,
      level: node.attrs.level as number,
      text: node.textContent,
    })
    return false
  })
  return headings
}

/**
 * The document's headings as a table of contents, read from the document
 * itself so it never writes anchors into the content. The section holding
 * the caret is marked; choosing a heading moves the caret there.
 */
export function OutlinePanel({
  editor,
  className,
}: {
  editor: Editor
  className?: string
}) {
  const { headings, current } = useEditorState({
    editor,
    selector: ({ editor }) => {
      if (editor.isDestroyed) return { headings: [], current: null }
      const headings = readHeadings(editor)
      const caret = editor.state.selection.from
      const current = headings.findLast((heading) => heading.pos < caret)
      return { headings, current: current?.pos ?? null }
    },
  })
  const top = Math.min(...headings.map((heading) => heading.level))

  const go = (heading: Heading) => {
    editor
      .chain()
      .focus()
      .command(({ tr }) => {
        tr.setSelection(TextSelection.near(tr.doc.resolve(heading.pos + 1)))
        return true
      })
      .run()
    // Scroll the editor's own content area, not the page around it.
    const dom = editor.view.nodeDOM(heading.pos)
    const scroller = editor.view.dom.closest("[data-slot=rich-text-scroll]")
    if (!(dom instanceof HTMLElement) || !scroller) return
    if (scroller.scrollHeight > scroller.clientHeight) {
      scroller.scrollTop +=
        dom.getBoundingClientRect().top -
        scroller.getBoundingClientRect().top -
        12
    } else dom.scrollIntoView({ block: "nearest" })
  }

  return (
    <nav
      aria-label="Outline"
      data-slot="rich-text-outline"
      className={cn(
        "flex w-[min(14rem,40%)] shrink-0 flex-col gap-1 overflow-y-auto border-l border-border px-2 py-3",
        className
      )}
    >
      <div className="px-2 pb-1 text-2xs font-medium text-muted-foreground">
        Outline
      </div>
      {headings.length === 0 ? (
        <p className="px-2 text-xs text-subtle">
          Headings you add appear here.
        </p>
      ) : (
        <ul className="flex flex-col">
          {headings.map((heading) => (
            <li key={heading.pos}>
              <button
                type="button"
                aria-current={heading.pos === current ? "location" : undefined}
                onClick={() => go(heading)}
                style={{
                  paddingLeft: `${0.5 + (heading.level - top) * 0.75}rem`,
                }}
                className={cn(
                  "flex w-full rounded-(--radius-item) py-1 pr-2 text-left text-xs text-muted-foreground hover:bg-muted hover:text-foreground aria-[current]:bg-muted aria-[current]:font-medium aria-[current]:text-foreground",
                  heading.level === top && "text-foreground"
                )}
              >
                <span className="line-clamp-2">
                  {heading.text || "Untitled"}
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </nav>
  )
}

/*
 * Rich text in Forge's terms: document typography at the 14px UI size,
 * every block Tiptap can hold, and the editor's own chrome (resize handles,
 * table selection, find results, drop cursor) painted from theme tokens so
 * it follows light and dark, contrast and the text-size preference.
 */
@import "katex/dist/katex.min.css";

/*
 * Text and highlight colours are stored in documents as these variables,
 * not hex values, so coloured text stays legible when the theme flips.
 */
:root {
  --rte-text-gray: oklch(0.55 0.012 260);
  --rte-text-red: oklch(0.55 0.19 25);
  --rte-text-orange: oklch(0.6 0.16 50);
  --rte-text-yellow: oklch(0.58 0.12 80);
  --rte-text-green: oklch(0.55 0.13 155);
  --rte-text-blue: oklch(0.52 0.16 256);
  --rte-text-purple: oklch(0.52 0.18 300);
  --rte-text-pink: oklch(0.56 0.18 347);
  --rte-highlight-gray: oklch(0.93 0.005 260);
  --rte-highlight-red: oklch(0.92 0.05 25);
  --rte-highlight-orange: oklch(0.93 0.06 60);
  --rte-highlight-yellow: oklch(0.95 0.09 95);
  --rte-highlight-green: oklch(0.93 0.06 155);
  --rte-highlight-blue: oklch(0.92 0.045 250);
  --rte-highlight-purple: oklch(0.92 0.05 300);
  --rte-highlight-pink: oklch(0.93 0.05 347);
  --rte-find: oklch(0.93 0.11 95);
  --rte-find-current: oklch(0.83 0.14 70);
}

.dark {
  --rte-text-gray: oklch(0.72 0.01 260);
  --rte-text-red: oklch(0.74 0.14 25);
  --rte-text-orange: oklch(0.78 0.13 55);
  --rte-text-yellow: oklch(0.84 0.13 90);
  --rte-text-green: oklch(0.78 0.12 155);
  --rte-text-blue: oklch(0.76 0.11 256);
  --rte-text-purple: oklch(0.76 0.12 300);
  --rte-text-pink: oklch(0.77 0.13 347);
  --rte-highlight-gray: oklch(0.32 0.008 260);
  --rte-highlight-red: oklch(0.34 0.07 25);
  --rte-highlight-orange: oklch(0.36 0.07 55);
  --rte-highlight-yellow: oklch(0.4 0.08 95);
  --rte-highlight-green: oklch(0.34 0.06 155);
  --rte-highlight-blue: oklch(0.34 0.06 256);
  --rte-highlight-purple: oklch(0.34 0.07 300);
  --rte-highlight-pink: oklch(0.35 0.07 347);
  --rte-find: oklch(0.45 0.09 95);
  --rte-find-current: oklch(0.58 0.13 70);
}

/* ---------------------------------------------------------------- base */

.rich-text .ProseMirror {
  min-height: inherit;
  padding: 0.75rem 1rem 1rem;
  outline: none;
  color: var(--foreground);
  font-size: var(--text-ui);
  line-height: 1.65;
  overflow-wrap: break-word;
  word-break: normal;
  caret-color: var(--foreground);
}

.rich-text[data-drag-handle] .ProseMirror {
  padding-left: 3.25rem;
}

/* The block handle follows the pointer; touch screens get the space back. */
@media (hover: none) {
  .rich-text[data-drag-handle] .ProseMirror {
    padding-left: 1rem;
  }

  .rich-text .drag-handle {
    display: none;
  }
}

.rich-text .ProseMirror > * + * {
  margin-top: 0.7em;
}

.rich-text .ProseMirror ::selection {
  background: color-mix(in oklch, var(--focus) 26%, transparent);
}

/* The selection stays visible while a dialog or menu has focus. */
.rich-text .ProseMirror .selection {
  background: color-mix(in oklch, var(--focus) 26%, transparent);
}

.rich-text .ProseMirror p.is-empty::before,
.rich-text .ProseMirror h1.is-empty::before,
.rich-text .ProseMirror h2.is-empty::before,
.rich-text .ProseMirror h3.is-empty::before,
.rich-text .ProseMirror h4.is-empty::before,
.rich-text .ProseMirror h5.is-empty::before,
.rich-text .ProseMirror h6.is-empty::before {
  content: attr(data-placeholder);
  float: left;
  height: 0;
  color: var(--subtle);
  pointer-events: none;
}

/* ---------------------------------------------------------------- text */

.rich-text .ProseMirror :is(h1, h2, h3, h4, h5, h6) {
  margin-top: 1.4em;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
  scroll-margin-top: 4rem;
}

.rich-text .ProseMirror > :is(h1, h2, h3, h4, h5, h6):first-child {
  margin-top: 0;
}

.rich-text .ProseMirror :is(h1, h2, h3, h4, h5, h6) + * {
  margin-top: 0.45em;
}

.rich-text .ProseMirror h1 {
  font-size: 1.5rem;
  letter-spacing: -0.02em;
}

.rich-text .ProseMirror h2 {
  font-size: 1.25rem;
}

.rich-text .ProseMirror h3 {
  font-size: 1.0625rem;
}

.rich-text .ProseMirror h4 {
  font-size: 0.9375rem;
}

.rich-text .ProseMirror h5 {
  font-size: var(--text-ui);
}

.rich-text .ProseMirror h6 {
  font-size: 0.75rem;
  color: var(--muted-foreground);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.rich-text .ProseMirror a {
  color: var(--primary);
  text-decoration: underline;
  text-decoration-color: color-mix(in oklch, var(--primary) 40%, transparent);
  text-underline-offset: 2px;
  cursor: text;
}

.rich-text .ProseMirror a:hover {
  text-decoration-color: var(--primary);
}

.rich-text:not([data-editable]) .ProseMirror a {
  cursor: pointer;
}

.rich-text .ProseMirror code {
  padding: 0.1em 0.3em;
  border: 1px solid var(--border);
  border-radius: var(--radius-chip);
  background: var(--muted);
  font-family: var(--font-mono);
  font-size: 0.85em;
}

.rich-text .ProseMirror mark {
  padding: 0.05em 0.15em;
  border-radius: 2px;
  background: var(--rte-highlight-yellow);
  color: inherit;
  box-decoration-break: clone;
}

.rich-text .ProseMirror :is(sub, sup) {
  font-size: 0.75em;
}

.rich-text .ProseMirror blockquote {
  padding-left: 1em;
  border-left: 2px solid
    color-mix(in oklch, var(--muted-foreground) 30%, transparent);
  color: var(--muted-foreground);
}

.rich-text .ProseMirror hr {
  margin: 1.4em 0;
  border: 0;
  border-top: 1px solid var(--border);
  cursor: pointer;
}

.rich-text .ProseMirror hr.ProseMirror-selectednode {
  border-top-color: var(--focus);
}

/* ---------------------------------------------------------------- lists */

.rich-text .ProseMirror :is(ul, ol) {
  padding-left: 1.45em;
}

.rich-text .ProseMirror ul {
  list-style: disc;
}

.rich-text .ProseMirror ul ul {
  list-style: circle;
}

.rich-text .ProseMirror ul ul ul {
  list-style: square;
}

.rich-text .ProseMirror ol {
  list-style: decimal;
}

.rich-text .ProseMirror ol ol {
  list-style: lower-alpha;
}

.rich-text .ProseMirror ol ol ol {
  list-style: lower-roman;
}

.rich-text .ProseMirror li + li,
.rich-text .ProseMirror li > :is(ul, ol) {
  margin-top: 0.2em;
}

.rich-text .ProseMirror li::marker {
  color: var(--muted-foreground);
}

.rich-text .ProseMirror ul[data-type="taskList"] {
  padding-left: 0.1em;
  list-style: none;
}

.rich-text .ProseMirror ul[data-type="taskList"] li {
  display: flex;
  align-items: flex-start;
  gap: 0.55em;
}

.rich-text .ProseMirror ul[data-type="taskList"] li > label {
  flex: none;
  margin-top: 0.3em;
  user-select: none;
}

.rich-text .ProseMirror ul[data-type="taskList"] li > label input {
  width: 0.95em;
  height: 0.95em;
  accent-color: var(--primary);
  cursor: pointer;
}

.rich-text .ProseMirror ul[data-type="taskList"] li > div {
  flex: 1 1 auto;
  min-width: 0;
}

.rich-text .ProseMirror ul[data-type="taskList"] li[data-checked="true"] > div {
  color: var(--muted-foreground);
  text-decoration: line-through;
  text-decoration-color: var(--subtle);
}

/* ---------------------------------------------------------------- code */

.rich-text .ProseMirror .code-block {
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
  background: color-mix(in oklch, var(--muted) 60%, var(--background));
}

.rich-text .ProseMirror .code-block-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.25rem 0.25rem 0 0.25rem;
  user-select: none;
}

.rich-text .ProseMirror pre {
  margin: 0;
  padding: 0.35rem 1rem 0.85rem;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  tab-size: 2;
  white-space: pre;
}

.rich-text .ProseMirror pre code {
  padding: 0;
  border: 0;
  background: none;
  font-size: inherit;
  color: var(--foreground);
}

/* Syntax colours from the validated data-viz set. */
.rich-text .hljs-comment,
.rich-text .hljs-quote {
  color: var(--subtle);
  font-style: italic;
}

.rich-text .hljs-keyword,
.rich-text .hljs-selector-tag,
.rich-text .hljs-meta .hljs-keyword,
.rich-text .hljs-doctag {
  color: var(--viz-5);
}

.rich-text .hljs-string,
.rich-text .hljs-regexp,
.rich-text .hljs-addition,
.rich-text .hljs-meta .hljs-string {
  color: var(--diff-added);
}

.rich-text .hljs-number,
.rich-text .hljs-literal,
.rich-text .hljs-symbol,
.rich-text .hljs-bullet,
.rich-text .hljs-variable.language_ {
  color: var(--viz-3);
}

.rich-text .hljs-title,
.rich-text .hljs-title.function_,
.rich-text .hljs-section,
.rich-text .hljs-selector-id {
  color: var(--viz-1);
}

.rich-text .hljs-type,
.rich-text .hljs-built_in,
.rich-text .hljs-title.class_,
.rich-text .hljs-selector-class {
  color: var(--viz-2);
}

.rich-text .hljs-attr,
.rich-text .hljs-attribute,
.rich-text .hljs-name,
.rich-text .hljs-tag,
.rich-text .hljs-property {
  color: var(--viz-4);
}

.rich-text .hljs-deletion {
  color: var(--diff-removed);
}

.rich-text .hljs-meta,
.rich-text .hljs-template-variable {
  color: var(--muted-foreground);
}

.rich-text .hljs-emphasis {
  font-style: italic;
}

.rich-text .hljs-strong {
  font-weight: 600;
}

/* ---------------------------------------------------------------- tables */

.rich-text .ProseMirror .tableWrapper {
  margin: 1em 0;
  overflow-x: auto;
}

.rich-text .ProseMirror table {
  width: 100%;
  margin: 0;
  overflow: hidden;
  border-collapse: collapse;
  table-layout: fixed;
}

.rich-text .ProseMirror :is(td, th) {
  position: relative;
  min-width: 4em;
  padding: 0.4em 0.6em;
  border: 1px solid var(--border);
  vertical-align: top;
  text-align: left;
}

.rich-text .ProseMirror :is(td, th) > * + * {
  margin-top: 0.4em;
}

.rich-text .ProseMirror th {
  background: var(--muted);
  font-weight: 500;
}

.rich-text .ProseMirror .selectedCell::after {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: color-mix(in oklch, var(--focus) 16%, transparent);
  content: "";
  pointer-events: none;
}

.rich-text .ProseMirror .column-resize-handle {
  position: absolute;
  top: 0;
  right: -2px;
  bottom: -2px;
  width: 4px;
  background: var(--focus);
  pointer-events: none;
}

.rich-text .ProseMirror.resize-cursor {
  cursor: col-resize;
}

/* ---------------------------------------------------------------- media */

.rich-text .ProseMirror img {
  display: block;
  max-width: 100%;
  height: auto;
  border-radius: var(--radius-card);
}

.rich-text .ProseMirror [data-resize-container] {
  max-width: 100%;
}

.rich-text .ProseMirror [data-resize-wrapper] {
  max-width: 100%;
}

.rich-text
  .ProseMirror
  :is(img, [data-resize-container]).ProseMirror-selectednode
  img,
.rich-text .ProseMirror img.ProseMirror-selectednode {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.rich-text .ProseMirror [data-resize-handle] {
  z-index: 3;
  width: 0.625rem;
  height: 0.625rem;
  border: 1.5px solid var(--background);
  border-radius: 999px;
  background: var(--focus);
  opacity: 0;
  transition: opacity 120ms;
}

.rich-text .ProseMirror [data-resize-handle="top-left"] {
  margin: -0.3rem 0 0 -0.3rem;
  cursor: nwse-resize;
}

.rich-text .ProseMirror [data-resize-handle="top-right"] {
  margin: -0.3rem -0.3rem 0 0;
  cursor: nesw-resize;
}

.rich-text .ProseMirror [data-resize-handle="bottom-left"] {
  margin: 0 0 -0.3rem -0.3rem;
  cursor: nesw-resize;
}

.rich-text .ProseMirror [data-resize-handle="bottom-right"] {
  margin: 0 -0.3rem -0.3rem 0;
  cursor: nwse-resize;
}

.rich-text[data-editable]
  .ProseMirror
  [data-resize-container]:is(:hover, .ProseMirror-selectednode)
  [data-resize-handle] {
  opacity: 1;
}

.rich-text .ProseMirror :is(div[data-youtube-video], div[data-twitch-video]) {
  cursor: move;
}

.rich-text .ProseMirror iframe {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  border: 0;
  border-radius: var(--radius-card);
  background: var(--muted);
}

.rich-text[data-editable] .ProseMirror iframe {
  pointer-events: none;
}

.rich-text .ProseMirror .ProseMirror-selectednode :is(iframe, audio),
.rich-text .ProseMirror :is(iframe, audio).ProseMirror-selectednode {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.rich-text .ProseMirror audio {
  display: block;
  width: 100%;
  max-width: 32rem;
}

/* ---------------------------------------------------------------- math */

.rich-text .ProseMirror .tiptap-mathematics-render {
  border-radius: var(--radius-item);
}

.rich-text .ProseMirror .tiptap-mathematics-render--editable {
  cursor: pointer;
  transition: background-color 120ms;
}

.rich-text .ProseMirror .tiptap-mathematics-render--editable:hover {
  background: var(--muted);
}

.rich-text .ProseMirror [data-type="inline-math"] {
  display: inline-block;
  padding: 0 0.15em;
}

.rich-text .ProseMirror [data-type="block-math"] {
  display: block;
  padding: 0.6em 0;
  overflow-x: auto;
  text-align: center;
}

.rich-text .ProseMirror :is(.inline-math-error, .block-math-error) {
  color: var(--destructive);
  font-family: var(--font-mono);
  font-size: 0.85em;
}

.rich-text .ProseMirror .ProseMirror-selectednode.tiptap-mathematics-render {
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}

/* ---------------------------------------------------------------- details */

.rich-text .ProseMirror .details {
  display: flex;
  gap: 0.35rem;
  padding: 0.45rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
}

.rich-text .ProseMirror .details > button {
  display: grid;
  flex: none;
  place-items: center;
  width: 1.3rem;
  height: 1.3rem;
  margin-top: 0.12rem;
  padding: 0;
  border-radius: var(--radius-chip);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.55rem;
}

.rich-text .ProseMirror .details > button:hover {
  background: var(--muted);
  color: var(--foreground);
}

.rich-text .ProseMirror .details > button::before {
  content: "\25B6";
  transition: transform 120ms;
}

.rich-text .ProseMirror .details.is-open > button::before {
  transform: rotate(90deg);
}

.rich-text .ProseMirror .details > div {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}

.rich-text .ProseMirror .details summary {
  font-weight: 500;
  list-style: none;
}

.rich-text .ProseMirror .details summary::-webkit-details-marker {
  display: none;
}

.rich-text .ProseMirror .details [data-type="detailsContent"] {
  margin-top: 0.35em;
}

.rich-text .ProseMirror .details [data-type="detailsContent"] > * + * {
  margin-top: 0.7em;
}

/* ---------------------------------------------------------------- inline nodes */

.rich-text .ProseMirror .mention {
  padding: 0.05em 0.3em;
  border-radius: var(--radius-chip);
  background: var(--status-queued);
  color: var(--status-queued-foreground);
  font-weight: 500;
  box-decoration-break: clone;
}

.rich-text .ProseMirror [data-type="emoji"] img {
  display: inline-block;
  width: 1.1em;
  height: 1.1em;
  vertical-align: -0.2em;
}

/* ---------------------------------------------------------------- editing aids */

.rich-text .ProseMirror .find-and-replace-result {
  border-radius: 2px;
  background: var(--rte-find);
}

.rich-text .ProseMirror .find-and-replace-result-current {
  background: var(--rte-find-current);
}

.rich-text .ProseMirror .tiptap-invisible-character::before {
  color: var(--subtle);
}

/* Focus mode: everything but the block being written fades back. */
.rich-text[data-focus-mode] .ProseMirror > *:not(.has-focus) {
  opacity: 0.35;
  transition: opacity 150ms;
}

.rich-text .ProseMirror-gapcursor::after {
  border-top-color: var(--foreground);
}

import * as React from "react"
import {
  EditorContent,
  useEditor,
  useEditorState,
  type Editor,
  type JSONContent,
} from "@tiptap/react"
import { FloatingMenu } from "@tiptap/react/menus"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { toast } from "@/components/ui/toast"
import { Icon } from "../icon"
import { BlockHandle } from "./block-handle"
import { RichTextBubbleMenus } from "./bubble-menus"
import { readContent, sameContent, writeContent } from "./content"
import { createExtensions, type EditorHandlers } from "./extensions"
import { resolveFeatures } from "./features"
import { AUDIO_TYPES, IMAGE_TYPES, insertFiles } from "./files"
import { FindReplaceBar } from "./find-replace"
import { InsertDialog } from "./insert-dialog"
import { OutlinePanel } from "./outline"
import { RichTextToolbar } from "./toolbar"
import type {
  InsertDialogRequest,
  MentionSource,
  RichTextEditorHandle,
  RichTextFeatures,
  RichTextFormat,
  RichTextPreset,
  RichTextValue,
  UploadHandler,
} from "./types"
import "./rich-text-editor.css"

/** The value props, typed by format: strings for HTML and Markdown, JSON otherwise. */
type ValueProps =
  | {
      format?: "html" | "markdown"
      value?: string
      defaultValue?: string
      onChange?: (value: string, editor: Editor) => void
    }
  | {
      format: "json"
      value?: JSONContent
      defaultValue?: JSONContent
      onChange?: (value: JSONContent, editor: Editor) => void
    }

export type RichTextEditorProps = ValueProps & {
  /** Which feature groups are on; `features` overrides single ones. */
  preset?: RichTextPreset
  features?: Partial<RichTextFeatures>
  placeholder?: string
  /** Shows the content without editing; the toolbar hides unless `toolbar`. */
  readOnly?: boolean
  disabled?: boolean
  autoFocus?: boolean | "start" | "end"
  /** The most characters the document may hold; typing stops there. */
  maxLength?: number
  /** Show the fixed toolbar. Defaults to on while editable. */
  toolbar?: boolean
  /** Show word and character counts. Defaults to on except in `minimal`. */
  showCount?: boolean
  /** Enables `@` mentions, suggesting what the source returns. */
  mentions?: MentionSource
  /** Stores added files and returns their URLs; without it they're inlined. */
  onUpload?: UploadHandler
  /** Largest file that can be added, in bytes. Default 10 MB. */
  maxFileSize?: number
  /** Submits the value with a native form under this name. */
  name?: string
  id?: string
  "aria-label"?: string
  "aria-labelledby"?: string
  "aria-describedby"?: string
  "aria-invalid"?: boolean
  onFocus?: (editor: Editor) => void
  onBlur?: (editor: Editor) => void
  /** Called once the editor exists, with the Tiptap instance. */
  onReady?: (editor: Editor) => void
  /** Classes for the frame (border, radius, height). */
  className?: string
  /** Classes for the scrolling content area (min/max height). */
  contentClassName?: string
  /** Render without the field frame, for showing saved content. */
  bare?: boolean
  ref?: React.Ref<RichTextEditorHandle>
}

const DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024

/**
 * A complete rich text field on Tiptap: toolbar, selection and table menus,
 * `/` commands, block handles, find and replace, an outline, full screen,
 * uploads, embeds, formulas, and HTML, Markdown or JSON values. Use it
 * controlled (`value` + `onChange`) or uncontrolled (`defaultValue`).
 */
export function RichTextEditor(props: RichTextEditorProps) {
  const {
    format = "html",
    value,
    defaultValue,
    preset = "full",
    features: featureOverrides,
    readOnly = false,
    disabled = false,
    autoFocus = false,
    maxLength,
    toolbar,
    showCount,
    mentions,
    name,
    className,
    contentClassName,
    bare = false,
    ref,
  } = props

  const featuresKey = JSON.stringify(resolveFeatures(preset, featureOverrides))
  const features = React.useMemo<RichTextFeatures>(
    () => JSON.parse(featuresKey),
    [featuresKey]
  )
  const editable = !readOnly && !disabled

  // Everything the editor's callbacks need, current as of the last render.
  const latest = React.useRef({ props, format, editable })
  React.useLayoutEffect(() => {
    latest.current = { props, format, editable }
  })

  const fileInputRef = React.useRef<HTMLInputElement>(null)
  const hiddenInputRef = React.useRef<HTMLInputElement>(null)
  const [scrollElement, setScrollElement] =
    React.useState<HTMLDivElement | null>(null)
  const [dialog, setDialog] = React.useState<InsertDialogRequest | null>(null)
  const [findOpen, setFindOpen] = React.useState(false)
  const [outlineOpen, setOutlineOpen] = React.useState(false)
  const [fullscreen, setFullscreen] = React.useState(false)
  const [focusMode, setFocusMode] = React.useState(false)

  const fullscreenRef = React.useRef(fullscreen)
  React.useLayoutEffect(() => {
    fullscreenRef.current = fullscreen
  }, [fullscreen])

  // Stable for the editor's lifetime; callbacks read the latest props.
  const [handlers] = React.useState<EditorHandlers>(() => ({
    actions: {
      openDialog: (request) => setDialog(request),
      pickFiles: (kind) => {
        const input = fileInputRef.current
        if (!input) return
        input.accept = (kind === "image" ? IMAGE_TYPES : AUDIO_TYPES).join(",")
        input.click()
      },
      toggleFind: (open) => setFindOpen((was) => open ?? !was),
      toggleOutline: (open) => setOutlineOpen((was) => open ?? !was),
      toggleFullscreen: (open) => setFullscreen((was) => open ?? !was),
    },
    insertFiles: (editor, files, pos) =>
      void insertFiles(editor, files, {
        upload: latest.current.props.onUpload,
        maxFileSize: latest.current.props.maxFileSize ?? DEFAULT_MAX_FILE_SIZE,
        pos,
        onError: (message) =>
          toast.add({
            title: "File not added",
            description: message,
            type: "error",
          }),
      }),
    isEditable: () => latest.current.editable,
    placeholder: () => latest.current.props.placeholder ?? "Write something…",
    mentions: (query, signal) =>
      latest.current.props.mentions?.(query, signal) ?? [],
    isFullscreen: () => fullscreenRef.current,
  }))
  const { actions } = handlers

  const hasMentions = Boolean(mentions)
  const extensions = React.useMemo(
    () =>
      createExtensions({
        features,
        maxLength,
        mentions: hasMentions,
        handlers,
      }),
    [features, maxLength, hasMentions, handlers]
  )

  const initial = value ?? defaultValue
  const lastValue = React.useRef<RichTextValue | undefined>(initial)

  const editor = useEditor(
    {
      extensions,
      content: initial ?? "",
      contentType: typeof initial === "string" ? format : "json",
      editable,
      autofocus: autoFocus === true ? "end" : autoFocus || false,
      editorProps: {
        attributes: editorAttributes(props, editable),
      },
      onUpdate: ({ editor }) => {
        const { props, format } = latest.current
        const next = readContent(editor, format)
        lastValue.current = next
        if (hiddenInputRef.current) {
          hiddenInputRef.current.value = serialize(next)
        }
        ;(
          props.onChange as
            ((value: RichTextValue, editor: Editor) => void) | undefined
        )?.(next, editor)
      },
      onFocus: ({ editor }) => latest.current.props.onFocus?.(editor),
      onBlur: ({ editor }) => latest.current.props.onBlur?.(editor),
      onCreate: ({ editor }) => latest.current.props.onReady?.(editor),
    },
    [extensions]
  )

  // A new `value` from outside replaces the document; our own echo doesn't.
  React.useEffect(() => {
    if (value === undefined) return
    if (sameContent(value, lastValue.current)) return
    lastValue.current = value
    if (sameContent(value, readContent(editor, format))) return
    writeContent(editor, value, format)
    if (hiddenInputRef.current) hiddenInputRef.current.value = serialize(value)
  }, [editor, value, format])

  React.useEffect(() => {
    editor.setEditable(editable, false)
  }, [editor, editable])

  const attributesKey = JSON.stringify(editorAttributes(props, editable))
  React.useEffect(() => {
    editor.setOptions({
      editorProps: { attributes: JSON.parse(attributesKey) },
    })
  }, [editor, attributesKey])

  React.useImperativeHandle(
    ref,
    (): RichTextEditorHandle => ({
      editor,
      focus: (position = "end") => editor.commands.focus(position),
      clear: () => editor.commands.clearContent(true),
      getValue: ((valueFormat?: RichTextFormat) =>
        readContent(
          editor,
          valueFormat ?? format
        )) as RichTextEditorHandle["getValue"],
      setValue: (next, valueFormat) => {
        writeContent(editor, next, valueFormat ?? format)
        lastValue.current = readContent(editor, format)
      },
    }),
    [editor, format]
  )

  // Full screen owns the page: no scrolling behind it.
  React.useEffect(() => {
    if (!fullscreen) return
    const root = document.documentElement
    const previous = root.style.overflow
    root.style.overflow = "hidden"
    return () => {
      root.style.overflow = previous
    }
  }, [fullscreen])

  // StrictMode and concurrent retries can render once more with an editor
  // Tiptap has already destroyed (no schema, no storage); the replacement
  // arrives with the next render.
  if (editor.isDestroyed) return null

  const showToolbar = toolbar ?? editable
  const outlineAvailable = features.outline && features.headings
  const counting =
    showCount ?? (preset !== "minimal" || maxLength !== undefined)

  return (
    <div
      // useEditorState keeps reading a replaced editor until its next
      // transaction, so the parts that use it remount with each instance.
      key={editor.instanceId}
      data-slot="rich-text-editor"
      data-fullscreen={fullscreen || undefined}
      data-disabled={disabled || undefined}
      inert={disabled}
      onKeyDown={(event) => {
        if (event.key === "Escape" && fullscreen && !event.defaultPrevented) {
          setFullscreen(false)
        }
      }}
      className={cn(
        // No container query here: containment would re-anchor the
        // fixed-position menus inside to this frame.
        "relative flex min-w-0 flex-col text-foreground",
        !bare &&
          "rounded-(--radius-control) border border-border bg-background transition-[color,box-shadow] duration-200 has-[.ProseMirror-focused]:border-ring has-[.ProseMirror-focused]:ring-3 has-[.ProseMirror-focused]:ring-ring/30",
        !bare &&
          props["aria-invalid"] &&
          "border-destructive ring-3 ring-destructive/20 has-[.ProseMirror-focused]:border-destructive has-[.ProseMirror-focused]:ring-destructive/20",
        disabled && "cursor-not-allowed opacity-50",
        fullscreen &&
          "fixed inset-0 z-50 rounded-none border-0 ring-0 has-[.ProseMirror-focused]:ring-0",
        className
      )}
    >
      {showToolbar && (
        <RichTextToolbar
          editor={editor}
          features={features}
          actions={actions}
          view={{ findOpen, outlineOpen, fullscreen, focusMode }}
          onFocusModeChange={setFocusMode}
        />
      )}
      {findOpen && features.findReplace && (
        <FindReplaceBar editor={editor} onClose={() => setFindOpen(false)} />
      )}

      <div className="flex min-h-0 flex-1">
        <div
          ref={setScrollElement}
          data-slot="rich-text-scroll"
          className={cn(
            "min-h-0 min-w-0 flex-1 overflow-y-auto",
            !bare && "min-h-32",
            contentClassName,
            // Full screen gives the content the whole height.
            fullscreen && "max-h-none"
          )}
        >
          <EditorContent
            editor={editor}
            data-editable={editable || undefined}
            data-drag-handle={(editable && features.dragHandle) || undefined}
            data-focus-mode={focusMode || undefined}
            className={cn(
              "rich-text relative min-h-[inherit]",
              bare && "[&_.ProseMirror]:p-0",
              // A readable measure when the editor fills the screen.
              fullscreen && "mx-auto max-w-[52rem] py-6"
            )}
          />
        </div>
        {outlineOpen && outlineAvailable && <OutlinePanel editor={editor} />}
      </div>

      {counting && <CountFooter editor={editor} maxLength={maxLength} />}

      {editable && scrollElement && (
        <RichTextBubbleMenus
          editor={editor}
          actions={actions}
          scrollTarget={scrollElement}
        />
      )}
      {editable && features.dragHandle && (
        <BlockHandle editor={editor} actions={actions} />
      )}
      {editable && features.slashCommands && !features.dragHandle && (
        <FloatingMenu
          editor={editor}
          options={{ placement: "left", offset: 6 }}
          className="z-20"
        >
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Insert a block"
            onClick={() => editor.chain().focus().insertContent("/").run()}
            className="text-subtle hover:text-foreground"
          >
            <Icon icon="plus" />
          </Button>
        </FloatingMenu>
      )}

      <InsertDialog
        editor={editor}
        request={dialog}
        actions={actions}
        onClose={() => setDialog(null)}
      />
      <input
        ref={fileInputRef}
        type="file"
        multiple
        hidden
        tabIndex={-1}
        onChange={(event) => {
          const files = Array.from(event.target.files ?? [])
          event.target.value = ""
          if (files.length) handlers.insertFiles(editor, files)
        }}
      />
      {name && (
        <input
          ref={hiddenInputRef}
          type="hidden"
          name={name}
          defaultValue={serialize(initial ?? "")}
        />
      )}
    </div>
  )
}

function serialize(value: RichTextValue) {
  return typeof value === "string" ? value : JSON.stringify(value)
}

function editorAttributes(props: RichTextEditorProps, editable: boolean) {
  const attributes: Record<string, string> = {
    role: "textbox",
    "aria-multiline": "true",
  }
  if (props.id) attributes.id = props.id
  if (props["aria-label"]) attributes["aria-label"] = props["aria-label"]
  if (props["aria-labelledby"]) {
    attributes["aria-labelledby"] = props["aria-labelledby"]
  }
  if (props["aria-describedby"]) {
    attributes["aria-describedby"] = props["aria-describedby"]
  }
  if (props["aria-invalid"]) attributes["aria-invalid"] = "true"
  if (!editable) attributes["aria-readonly"] = "true"
  return attributes
}

/** Words and characters, and the limit when there is one. */
function CountFooter({
  editor,
  maxLength,
}: {
  editor: Editor
  maxLength?: number
}) {
  const count = useEditorState({
    editor,
    selector: ({ editor }) =>
      editor.isDestroyed
        ? null
        : {
            characters: editor.storage.characterCount.characters(),
            words: editor.storage.characterCount.words(),
          },
  })
  if (!count) return null
  const near = maxLength !== undefined && count.characters >= maxLength * 0.9
  return (
    <div
      data-slot="rich-text-count"
      className="flex items-center justify-end gap-3 border-t border-border px-3 py-1 text-2xs text-subtle tabular-nums"
    >
      <span>
        {count.words} {count.words === 1 ? "word" : "words"}
      </span>
      <span
        aria-live={near ? "polite" : undefined}
        className={cn(near && "text-destructive")}
      >
        {maxLength !== undefined
          ? `${count.characters} / ${maxLength} characters`
          : `${count.characters} ${count.characters === 1 ? "character" : "characters"}`}
      </span>
    </div>
  )
}

/**
 * Saved rich text, shown read-only with the editor's typography. Pass the
 * same `format` it was saved in.
